<script setup lang="ts">
import {ref,computed} from 'vue'
import {onShow} from '@dcloudio/uni-app'
import PageShell from '../../components/PageShell.vue'
import AppIcon from '../../components/AppIcon.vue'
import {useUserStore} from '../../stores/user'
import {landing} from '../../utils/navigation'
import {errorText} from '../../utils/format'
const store=useUserStore(),checked=ref(false),busy=ref(false),error=ref('')
const employee=computed(()=>store.challenge?.employee)
const rows=computed(()=>[
 {label:'职工姓名',value:employee.value?.name,strong:true},{label:'职工工号',value:employee.value?.employeeNo,strong:true},
 {label:'性别',value:employee.value?.gender},{label:'出生日期',value:employee.value?.birthDate},
 {label:'所属单位',value:employee.value?.organization},{label:'所属班组',value:employee.value?.team},
 {label:'岗位工种',value:employee.value?.position},{label:'联系电话',value:employee.value?.phoneMasked},
])
onShow(async()=>{await store.restore();if(!store.profile){uni.reLaunch({url:'/pages/login/index'});return}if(store.profile.bound){uni.reLaunch({url:landing(store.profile)});return}if(!store.validChallenge()){store.clearChallenge();uni.redirectTo({url:'/pages/login/bind'})}})
function verifyAgain(){if(busy.value)return;store.clearChallenge();uni.redirectTo({url:'/pages/login/bind'})}
function mismatch(){uni.showModal({title:'请联系企业管理员核对',content:'姓名、工号和企业资料由后台提供。请先由企业管理员核对修改，然后重新输入个人专属验证码验证；本页不会覆盖后台身份资料。',confirmText:'重新验证',cancelText:'返回核对',success:r=>{if(r.confirm)verifyAgain()}})}
async function confirm(){
 if(!checked.value||busy.value)return
 busy.value=true;error.value=''
 try{await store.confirmBinding();if(store.profile)uni.reLaunch({url:landing(store.profile)})}catch(e){error.value=errorText(e);checked.value=false}finally{busy.value=false}
}
</script>
<template><PageShell title="个人信息确认" :back="false"><view class="content confirm-content"><view v-if="employee" class="card confirm-card"><view class="confirmation-heading"><view class="person-mark"><AppIcon name="badge-check" :size="37"/></view><text class="confirm-title">个人信息确认</text><text class="confirm-subtitle">已校验企业职工档案，请核对本人信息</text></view><view class="section-head"><text class="section-title">职工基本信息</text><text class="tag matched">后台已匹配</text></view><view class="identity-list"><view v-for="row in rows" :key="row.label" class="identity-row"><text class="identity-label">{{row.label}}</text><text class="identity-value" :class="{strong:row.strong,missing:!row.value}">{{row.value||'未填写'}}</text></view></view><view class="information-note"><AppIcon name="info" :size="15"/><text>{{store.challenge?.notice||'以上信息由企业后台提供。信息有误时请联系企业管理员核对修改，再重新验证。'}}</text></view><view class="correction-link" @tap="!busy&&mismatch()">信息有误？联系管理员 ›</view><view class="identity-consent" @tap="!busy&&(checked=!checked)"><view class="confirm-checkbox" :class="{checked}"><AppIcon v-if="checked" name="check" color="white" :size="13"/></view><text>我已核对以上信息，确认与本人身份一致。</text></view><view v-if="error" class="alert">{{error}}</view><button class="btn confirm-button" :disabled="!checked||busy" :loading="busy" @tap="confirm">确认并进入矿安智康</button><button v-if="!store.validChallenge()&&!busy" class="btn btn-soft" style="margin-top:20rpx" @tap="verifyAgain">重新验证身份</button><view class="exit-link" @tap="!busy&&store.logout()">退出当前登录</view></view><view v-else class="card"><text class="paragraph">{{error||'确认凭据已失效，请重新验证身份后核对资料。'}}</text><button class="btn" style="margin-top:24rpx" @tap="verifyAgain">重新验证身份</button><view class="exit-link" @tap="store.logout()">退出当前登录</view></view></view></PageShell></template>
<style scoped>.confirm-content{padding:26rpx}.confirm-card{padding:28rpx 24rpx;border:1px solid #e1e9e4;border-radius:30rpx;box-shadow:none}.confirmation-heading{display:flex;align-items:center;flex-direction:column;padding:4rpx 0 35rpx}.person-mark{display:flex;padding:10rpx;color:#009e65}.confirm-title{font-size:35rpx;font-weight:650;margin-top:8rpx}.confirm-subtitle{font-size:23rpx;color:#839389;margin-top:8rpx}.section-title{font-size:29rpx}.matched{font-size:21rpx;padding:4rpx 13rpx;border-radius:25rpx;background:#e2f4e9}.identity-list{padding:0 13rpx}.identity-row{display:flex;align-items:center;justify-content:space-between;gap:30rpx;padding:27rpx 0;border-bottom:1px solid #edf0ee;min-height:93rpx;font-size:27rpx}.identity-row:last-child{border-bottom:0}.identity-label{color:#7a857e;font-size:25rpx;flex-shrink:0}.identity-value{color:#263b2e;text-align:right;word-break:break-word}.strong{font-weight:650}.missing{color:#a3afa7;font-size:24rpx}.information-note{background:#eaf6f2;display:flex;align-items:flex-start;gap:12rpx;padding:20rpx 16rpx;border-radius:12rpx;margin-top:21rpx;font-size:22rpx;line-height:1.8;color:#5e7768}.information-note image{margin-top:5rpx}.identity-consent{display:flex;align-items:flex-start;gap:16rpx;padding:27rpx 2rpx;font-size:25rpx;color:#354b3d;line-height:1.7}.confirm-checkbox{height:34rpx;width:34rpx;border:1px solid #c4cec7;border-radius:50%;flex-shrink:0;margin-top:4rpx;display:flex;align-items:center;justify-content:center}.checked{background:#00965a;border-color:#00965a}.confirm-button{font-size:27rpx;padding:22rpx;box-shadow:none}.confirm-button[disabled]{background:#edf0ee;color:#9ba59e;opacity:1}.correction-link{text-align:right;font-size:23rpx;color:#178957;padding:20rpx 0 0}.exit-link{text-align:center;color:#97a59b;font-size:23rpx;padding-top:25rpx}.inline-input{flex:1;min-width:0;max-width:65%;height:76rpx;padding:15rpx 16rpx;background:#f1f8f4;border:1px solid #dcebe1;border-radius:12rpx;text-align:right;font-size:25rpx}.inline-picker{flex:1;max-width:65%}.inline-select{height:76rpx;padding:17rpx 16rpx;display:flex;align-items:center;justify-content:space-between;gap:15rpx;background:#f1f8f4;border:1px solid #dcebe1;border-radius:12rpx;font-size:25rpx;color:#3d6a4e}.editing-note{font-size:22rpx;color:#72907e;line-height:1.8;margin-top:16rpx}</style>
